import Mathlib

/-!
# Counting primitive Dirichlet characters

Let `A(X)` be the number of primitive Dirichlet characters modulo `q` for `1 ≤ q ≤ X`.
This file formalizes the asymptotic

`A(X) = (18 / π⁴) · X² + O(X · (log X)²)`.

The error term stated in the original problem was `O(X · log X)`; that sharper bound (and even
`O(X)`, which numerics suggest) is true, but the elementary hyperbola method used here only yields
`O(X · (log X)²)`.  See the docstring of `A_asymptotic`.

## Note on the constant

The task as originally posed stated the leading constant as `3/π²`.  This is **incorrect**:
a direct numerical computation of `∑_{q ≤ X} (number of primitive characters mod q)` gives
`A(X)/X² → 0.184788… = 18/π⁴`, not `3/π² ≈ 0.3040`.  The correct constant is

`18 / π⁴ = (3/π²) · (6/π²) = 1 / (2 ζ(2)²)`,

which arises as `(3/π²) · ∑_{d} μ(d)/d²` with `∑_d μ(d)/d² = 6/π² = 1/ζ(2)`.
We therefore formalize the corrected statement.

## Number of primitive characters

The number of primitive Dirichlet characters modulo `q` is classically
`∑_{d ∣ q} μ(d) · φ(q/d)` (Möbius inversion of `φ(q) = ∑_{d ∣ q} (#primitive mod d)`).
We take this arithmetic expression as the definition `primCount q`.

## Proof outline

* `A_eq_moebius_totientSum` : interchanging the double sum,
  `A(X) = ∑_{d ≤ N} μ(d) · Φ(⌊N/d⌋)` where `N = ⌊X⌋` and `Φ(M) = ∑_{m ≤ M} φ(m)`.
* `hasSum_moebius_div_sq` : `∑_n μ(n)/n² = 6/π²` (via the L-series identity `ζ(s)·(∑μ(n)n^{-s}) = 1`).
* `totientSum_error` : `Φ(M) = (3/π²) M² + O(M log M)` (hyperbola method / Dirichlet convolution
  `φ = μ ⋆ id`).
* `A_asymptotic` : assembling the above.
-/

open scoped BigOperators
open ArithmeticFunction Filter Asymptotics

namespace PrimitiveDirichletCount

noncomputable section

/-- The number of primitive Dirichlet characters modulo `q`.  Classically this equals
`∑_{d ∣ q} μ(d) · φ(q/d)`, which we take as the definition. -/
def primCount (q : ℕ) : ℤ := ∑ d ∈ q.divisors, moebius d * (q / d).totient

/-- The summatory Euler totient function `Φ(M) = ∑_{1 ≤ m ≤ M} φ(m)`, as a real number. -/
def totientSum (M : ℕ) : ℝ := ∑ m ∈ Finset.Icc 1 M, (m.totient : ℝ)

/-- The counting function `A(x) = #{ primitive Dirichlet characters mod q : 1 ≤ q ≤ x }`. -/
def A (x : ℝ) : ℝ := ∑ q ∈ Finset.Icc 1 ⌊x⌋₊, (primCount q : ℝ)

/-
Rearranging the divisor sum: with `N = ⌊x⌋`,
`A(x) = ∑_{d ≤ N} μ(d) · Φ(⌊N/d⌋)`.
-/
lemma A_eq_moebius_totientSum (x : ℝ) :
    A x = ∑ d ∈ Finset.Icc 1 ⌊x⌋₊, (moebius d : ℝ) * totientSum (⌊x⌋₊ / d) := by
  simp +decide only [A, primCount];
  simp +decide [ totientSum, Finset.mul_sum _ _ _ ];
  rw [ Finset.sum_sigma', Finset.sum_sigma' ];
  refine' Finset.sum_bij ( fun y hy => ⟨ y.2, y.1 / y.2 ⟩ ) _ _ _ _ <;> simp +decide;
  · exact fun a ha₁ ha₂ ha₃ ha₄ => ⟨ ⟨ Nat.pos_of_dvd_of_pos ha₃ ha₁, Nat.le_trans ( Nat.le_of_dvd ha₁ ha₃ ) ha₂ ⟩, Nat.div_pos ( Nat.le_of_dvd ha₁ ha₃ ) ( Nat.pos_of_dvd_of_pos ha₃ ha₁ ), Nat.div_le_div_right ha₂ ⟩;
  · intro a₁ ha₁ ha₂ ha₃ ha₄ a₂ ha₅ ha₆ ha₇ ha₈ h₁ h₂; cases a₁; cases a₂; aesop;
  · exact fun b hb₁ hb₂ hb₃ hb₄ => ⟨ b.2 * b.1, b.1, ⟨ ⟨ by nlinarith, by nlinarith [ Nat.div_mul_le_self ( ⌊x⌋₊ ) b.1 ] ⟩, dvd_mul_left _ _, by nlinarith ⟩, by simp +decide [ Nat.mul_div_cancel _ hb₁ ] ⟩

/-
`∑_{n ≥ 1} μ(n)/n² = 6/π² = 1/ζ(2)`.
-/
lemma hasSum_moebius_div_sq :
    HasSum (fun n : ℕ => (moebius n : ℝ) / (n : ℝ) ^ 2) (6 / Real.pi ^ 2) := by
  convert Complex.hasSum_ofReal.mp ( _ ) using 1;
  -- We use the fact that `LSeries ↗μ 2 = 6 / π²`.
  have h_lseries : LSeries (fun n => (moebius n : ℂ)) 2 = 6 / Real.pi ^ 2 := by
    have h_zeta : LSeries (fun n => (zeta n : ℂ)) 2 = (Real.pi : ℂ) ^ 2 / 6 := by
      convert riemannZeta_two using 1;
      rw [ LSeries_zeta_eq_riemannZeta ] ; norm_num;
    convert congr_arg ( fun x : ℂ => x⁻¹ ) ( h_zeta ) using 1;
    · rw [ inv_eq_of_mul_eq_one_right ];
      convert LSeries_zeta_mul_Lseries_moebius _ using 1 ; norm_num;
    · norm_num;
  convert h_lseries ▸ LSeriesSummable.LSeriesHasSum _ using 1;
  · norm_num [ LSeriesHasSum ];
    congr! 2;
    by_cases h : ‹_› = 0 <;> simp +decide [ h, LSeries.term ];
  · convert LSeriesSummable_moebius_iff.mpr _ using 1 ; norm_num

/-
Rearranging: `Φ(M) = ∑_{d ≤ M} μ(d) · (∑_{k ≤ ⌊M/d⌋} k)`, using `φ = μ ⋆ id`.
-/
lemma totientSum_rearrange (M : ℕ) :
    totientSum M
      = ∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) * ∑ k ∈ Finset.Icc 1 (M / d), (k : ℝ) := by
  -- Apply the pointwise Möbius expansion of the totient function.
  have h_pointwise : ∀ m : ℕ, m > 0 → (m.totient : ℝ) = ∑ d ∈ Nat.divisors m, (moebius d : ℝ) * ((m / d : ℕ) : ℝ) := by
    intro m hm_pos
    have h_sum_eq : ∑ x ∈ m.divisorsAntidiagonal, (moebius x.1 : ℝ) * (x.2 : ℝ) = ∑ d ∈ m.divisors, (moebius d : ℝ) * ((m / d : ℕ) : ℝ) := by
      refine' Finset.sum_bij ( fun x hx => x.1 ) _ _ _ _ <;> simp_all +decide [ Nat.divisorsAntidiagonal ];
      · intros; subst_vars; exact ⟨ dvd_of_mul_right_eq _ ‹_›, hm_pos.ne' ⟩ ;
      · aesop;
      · exact fun b hb _ => ⟨ ⟨ Nat.pos_of_dvd_of_pos hb hm_pos, Nat.le_of_dvd hm_pos hb ⟩, Nat.mul_div_cancel' hb ⟩;
    have := @ArithmeticFunction.sum_eq_iff_sum_mul_moebius_eq;
    specialize @this ℤ ( by infer_instance ) ( fun n => ( n.totient : ℤ ) ) ( fun n => ( n : ℤ ) ) ; norm_cast at *;
    exact h_sum_eq ▸ mod_cast this.mp ( fun n hn => Nat.sum_totient n ) m hm_pos ▸ rfl;
  simp +decide only [totientSum, Finset.mul_sum _ _ _];
  rw [ Finset.sum_congr rfl fun m hm => h_pointwise m <| Finset.mem_Icc.mp hm |>.1 ];
  rw [ Finset.sum_sigma', Finset.sum_sigma' ];
  refine' Finset.sum_bij ( fun x hx => ⟨ x.snd, x.fst / x.snd ⟩ ) _ _ _ _ <;> norm_num;
  · exact fun a ha₁ ha₂ ha₃ ha₄ => ⟨ ⟨ Nat.pos_of_dvd_of_pos ha₃ ha₁, Nat.le_trans ( Nat.le_of_dvd ha₁ ha₃ ) ha₂ ⟩, Nat.div_pos ( Nat.le_of_dvd ha₁ ha₃ ) ( Nat.pos_of_dvd_of_pos ha₃ ha₁ ), Nat.div_le_div_right ha₂ ⟩;
  · intro a₁ ha₁₁ ha₁₂ ha₁₃ ha₁₄ a₂ ha₂₁ ha₂₂ ha₂₃ ha₂₄ h₁ h₂; cases a₁; cases a₂; aesop;
  · exact fun b hb₁ hb₂ hb₃ hb₄ => ⟨ b.fst * b.snd, b.fst, ⟨ ⟨ by nlinarith, by nlinarith [ Nat.div_mul_le_self M b.fst ] ⟩, by norm_num, by nlinarith ⟩, by simp +decide [ Nat.mul_div_cancel_left _ hb₁ ] ⟩

/-
Gauss summation.
-/
lemma sum_Icc_one_id (j : ℕ) :
    ∑ k ∈ Finset.Icc 1 j, (k : ℝ) = (j : ℝ) * ((j : ℝ) + 1) / 2 := by
  exact Nat.recOn j ( by norm_num ) fun n ih => by erw [ Finset.sum_Ioc_succ_top ( by positivity ), ih ] ; push_cast ; ring;

/-
`∑_{d ≤ M} μ(d) ⌊M/d⌋ = 1` for `M ≥ 1` (from `μ ⋆ ζ = δ`).
-/
lemma moebius_mul_floor_sum (M : ℕ) (hM : 1 ≤ M) :
    ∑ d ∈ Finset.Icc 1 M, moebius d * ((M / d : ℕ) : ℤ) = 1 := by
  have h_sum : ∑ d ∈ Finset.Icc 1 M, moebius d * (∑ k ∈ Finset.Icc 1 (M / d), 1 : ℤ) = ∑ n ∈ Finset.Icc 1 M, ∑ d ∈ Nat.divisors n, moebius d := by
    simp +decide only [Finset.mul_sum _ _ _];
    rw [ Finset.sum_sigma', Finset.sum_sigma' ];
    refine' Finset.sum_bij ( fun x hx => ⟨ x.1 * x.2, x.1 ⟩ ) _ _ _ _ <;> simp_all +decide;
    · exact fun a ha₁ ha₂ ha₃ ha₄ => ⟨ ⟨ by nlinarith, by nlinarith [ Nat.div_mul_le_self M a.fst ] ⟩, by linarith, by linarith ⟩;
    · aesop;
    · exact fun b hb₁ hb₂ hb₃ hb₄ => ⟨ b.snd, b.fst / b.snd, ⟨ ⟨ Nat.pos_of_dvd_of_pos hb₃ hb₁, Nat.le_trans ( Nat.le_of_dvd hb₁ hb₃ ) hb₂ ⟩, Nat.div_pos ( Nat.le_of_dvd hb₁ hb₃ ) ( Nat.pos_of_dvd_of_pos hb₃ hb₁ ), Nat.div_le_div_right hb₂ ⟩, by rw [ Nat.mul_div_cancel' hb₃ ] ⟩;
  -- Now use the fact that $\sum_{d \mid n} \mu(d)$ is $1$ if $n = 1$ and $0$ otherwise.
  have h_moebius_sum : ∀ n : ℕ, 1 ≤ n → ∑ d ∈ Nat.divisors n, moebius d = if n = 1 then 1 else 0 := by
    intro n hn
    have h_sum : ∑ d ∈ Nat.divisors n, (moebius d : ℤ) = (ArithmeticFunction.moebius * ArithmeticFunction.zeta) n := by
      rw [ArithmeticFunction.coe_mul_zeta_apply]
    erw [ h_sum, ArithmeticFunction.moebius_mul_coe_zeta ] ; aesop;
  convert h_sum using 1;
  · norm_num;
  · rw [ Finset.sum_congr rfl fun n hn => h_moebius_sum n <| Finset.mem_Icc.mp hn |>.1 ] ; aesop

/-
Tail bound for the partial sums of `∑ μ(n)/n²`.
-/
lemma moebius_div_sq_tail (M : ℕ) (hM : 1 ≤ M) :
    |6 / Real.pi ^ 2 - ∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) / (d : ℝ) ^ 2|
      ≤ 1 / (M : ℝ) := by
  -- Let `f n = (moebius n : ℝ)/(n:ℝ)^2`. By `hasSum_moebius_div_sq`, `HasSum f (6/π²)`, so `6/π² = ∑' n, f n`.
  have h_sum : HasSum (fun n : ℕ => (moebius n : ℝ) / (n : ℝ) ^ 2) (6 / Real.pi ^ 2) := by
    convert hasSum_moebius_div_sq using 1;
  -- Bound its absolute value: `|∑'_{n ≥ M+1} f n| ≤ ∑'_{n ≥ M+1} |f n| ≤ ∑'_{n ≥ M+1} 1/n²`, using `|f n| = |moebius n|/n² ≤ 1/n²` (since `|moebius n| ≤ 1`, `abs_moebius_le_one` or from `moebius_eq_or`).
  have h_abs_sum : abs ((∑' n : ℕ, (moebius (n + M + 1) : ℝ) / ((n + M + 1) : ℝ) ^ 2)) ≤ ∑' n : ℕ, (1 : ℝ) / ((n + M + 1) : ℝ) ^ 2 := by
    refine' le_trans ( le_of_eq ( by rw [ ← Real.norm_eq_abs ] ) ) ( le_trans ( norm_tsum_le_tsum_norm _ ) _ );
    · exact_mod_cast h_sum.summable.norm.comp_injective ( add_left_injective ( M + 1 ) );
    · refine' Summable.tsum_le_tsum _ _ _;
      · norm_num [ ArithmeticFunction.moebius ];
        intro i; split_ifs <;> norm_num;
        positivity;
      · have := h_sum.summable.norm;
        exact_mod_cast this.comp_injective ( add_left_injective ( M + 1 ) );
      · exact_mod_cast summable_nat_add_iff ( M + 1 ) |>.2 <| Real.summable_one_div_nat_pow.2 one_lt_two;
  -- Finally `∑_{n ≥ M+1} 1/n² ≤ 1/M`: compare `1/n² ≤ 1/(n(n-1)) = 1/(n-1) - 1/n` for `n ≥ 2` and telescope from `M+1`, OR use the known bound.
  have h_sum_bound : ∑' n : ℕ, (1 : ℝ) / ((n + M + 1) : ℝ) ^ 2 ≤ 1 / (M : ℝ) := by
    -- We'll use the fact that $\sum_{n=M+1}^{\infty} \frac{1}{n^2}$ is a well-known sum that converges to $\frac{1}{M}$.
    have h_sum_bound : ∑' n : ℕ, (1 : ℝ) / ((n + M + 1) : ℝ) ^ 2 ≤ ∑' n : ℕ, (1 : ℝ) / ((n + M) * (n + M + 1)) := by
      refine' Summable.tsum_le_tsum _ _ _;
      · exact fun n => by gcongr ; nlinarith only [ show ( M : ℝ ) ≥ 1 by norm_cast ] ;
      · exact_mod_cast summable_nat_add_iff ( M + 1 ) |>.2 <| Real.summable_one_div_nat_pow.2 one_lt_two;
      · exact Summable.of_nonneg_of_le ( fun n => by positivity ) ( fun n => by rw [ div_le_div_iff₀ ] <;> norm_cast <;> ring <;> nlinarith ) ( summable_nat_add_iff M |>.2 <| Real.summable_one_div_nat_pow.2 one_lt_two );
    -- Notice that $\sum_{n=M}^{\infty} \frac{1}{n(n+1)}$ is a telescoping series.
    have h_telescope : ∀ N : ℕ, ∑ n ∈ Finset.range N, (1 : ℝ) / ((n + M) * (n + M + 1)) = 1 / (M : ℝ) - 1 / (N + M : ℝ) := by
      intro N; induction N <;> simp_all +decide [ Finset.sum_range_succ ];
      -- Combine and simplify the terms on the left-hand side.
      field_simp
      ring;
    -- Taking the limit of the telescoping series as $N$ approaches infinity, we get $\sum_{n=M}^{\infty} \frac{1}{n(n+1)} = \frac{1}{M}$.
    have h_limit : Filter.Tendsto (fun N : ℕ => ∑ n ∈ Finset.range N, (1 : ℝ) / ((n + M) * (n + M + 1))) Filter.atTop (nhds (1 / (M : ℝ))) := by
      simpa only [ h_telescope ] using by simpa using tendsto_const_nhds.sub ( tendsto_inv_atTop_zero.comp ( show Filter.Tendsto ( fun N : ℕ => ( N : ℝ ) + M ) Filter.atTop ( Filter.atTop ) by exact Filter.tendsto_atTop_add_const_right _ _ tendsto_natCast_atTop_atTop ) ) ;
    exact h_sum_bound.trans ( le_of_tendsto_of_tendsto' ( by exact ( Summable.hasSum <| by exact ( by { by_contra h; exact not_tendsto_atTop_of_tendsto_nhds ( h_limit ) <| by exact not_summable_iff_tendsto_nat_atTop_of_nonneg ( fun _ => by positivity ) |>.1 h } ) ) |> HasSum.tendsto_sum_nat ) h_limit fun N => by aesop );
  convert h_abs_sum.trans h_sum_bound using 1;
  rw [ ← h_sum.tsum_eq, ← Summable.sum_add_tsum_nat_add ( M + 1 ) ];
  · erw [ Finset.sum_Ico_eq_sub _ _ ] <;> norm_num [ add_assoc, Finset.sum_range_succ' ];
  · exact h_sum.summable

/-
Harmonic sum bound.
-/
lemma sum_Icc_one_div_le (M : ℕ) :
    ∑ d ∈ Finset.Icc 1 M, (1 : ℝ) / (d : ℝ) ≤ 1 + Real.log M := by
  convert harmonic_le_one_add_log M using 1;
  erw [ Finset.sum_Ico_eq_sum_range ] ; norm_num [ harmonic ];
  ac_rfl

/-
Totient summatory asymptotic with an explicit uniform error bound:
`Φ(M) = (3/π²) M² + O(M log M)`.
-/
lemma totientSum_error :
    ∃ C : ℝ, 0 ≤ C ∧ ∀ M : ℕ,
      |totientSum M - (3 / Real.pi ^ 2) * (M : ℝ) ^ 2|
        ≤ C * ((M : ℝ) * Real.log (M + 1) + 1) := by
  have h_C : ∃ C : ℝ, ∀ M : ℕ, M ≥ 1 → |totientSum M - 3 / Real.pi ^ 2 * (M : ℝ) ^ 2| ≤ C * ((M : ℝ) * Real.log (M + 1) + 1) := by
    -- We'll use the fact that $|S2 - (6 / \pi^2) M^2| \leq 2M \sum_{d=1}^M \frac{1}{d} + M$.
    have h_bound : ∀ M : ℕ, M ≥ 1 → |∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) * ((M / d : ℕ) : ℝ) ^ 2 - (6 / Real.pi ^ 2) * (M : ℝ) ^ 2| ≤ 2 * M * (∑ d ∈ Finset.Icc 1 M, (1 : ℝ) / (d : ℝ)) + M := by
      intros M hM
      have h_bound : |∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) * ((M / d : ℕ) : ℝ) ^ 2 - (∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) / (d : ℝ) ^ 2) * (M : ℝ) ^ 2| ≤ 2 * M * (∑ d ∈ Finset.Icc 1 M, (1 : ℝ) / (d : ℝ)) := by
        have h_bound : ∀ d ∈ Finset.Icc 1 M, |(moebius d : ℝ) * ((M / d : ℕ) : ℝ) ^ 2 - (moebius d : ℝ) / (d : ℝ) ^ 2 * (M : ℝ) ^ 2| ≤ 2 * (M : ℝ) / (d : ℝ) := by
          intros d hd
          have h_term_bound : |((M / d : ℕ) : ℝ) ^ 2 - (M : ℝ) ^ 2 / (d : ℝ) ^ 2| ≤ 2 * (M : ℝ) / (d : ℝ) := by
            have h_floor : (M / d : ℕ) ≤ (M : ℝ) / d ∧ (M : ℝ) / d < (M / d : ℕ) + 1 := by
              exact ⟨ by rw [ le_div_iff₀ ( Nat.cast_pos.mpr <| Finset.mem_Icc.mp hd |>.1 ) ] ; norm_cast; linarith [ Nat.div_mul_le_self M d ], by rw [ div_lt_iff₀ ( Nat.cast_pos.mpr <| Finset.mem_Icc.mp hd |>.1 ) ] ; norm_cast; linarith [ Nat.div_add_mod M d, Nat.mod_lt M ( Finset.mem_Icc.mp hd |>.1 ) ] ⟩;
            rw [ abs_le ] ; constructor <;> ring_nf at * <;> nlinarith [ show ( 0 :ℝ ) ≤ M / d by positivity ] ;
          have h_moebius_bound : |(moebius d : ℝ)| ≤ 1 := by
            simp [moebius];
            split_ifs <;> norm_num;
          rw [ abs_le ] at *;
          constructor <;> ring_nf at * <;> nlinarith;
        simpa [ Finset.mul_sum _ _ _, mul_assoc, mul_comm, mul_left_comm, div_eq_mul_inv, Finset.sum_mul ] using Finset.abs_sum_le_sum_abs _ _ |> le_trans <| Finset.sum_le_sum h_bound;
      have h_bound : |(∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) / (d : ℝ) ^ 2) - (6 / Real.pi ^ 2)| ≤ 1 / (M : ℝ) := by
        simpa only [ abs_sub_comm ] using moebius_div_sq_tail M hM;
      rw [ abs_le ] at *;
      constructor <;> nlinarith [ show ( M : ℝ ) ≥ 1 by norm_cast, one_div_mul_cancel ( by positivity : ( M : ℝ ) ≠ 0 ), pow_two ( M : ℝ ) ];
    -- Using the bound from h_bound, we can write
    have h_totient_bound : ∀ M : ℕ, M ≥ 1 → |totientSum M - (3 / Real.pi ^ 2) * (M : ℝ) ^ 2| ≤ (2 * M * (∑ d ∈ Finset.Icc 1 M, (1 : ℝ) / (d : ℝ)) + M) / 2 + 1 / 2 := by
      intro M hM
      have h_totient_sum : totientSum M = (∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) * ((M / d : ℕ) : ℝ) ^ 2) / 2 + (∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) * ((M / d : ℕ) : ℝ)) / 2 := by
        rw [ totientSum_rearrange M ];
        rw [ Finset.sum_div, Finset.sum_div ] ; rw [ ← Finset.sum_add_distrib ] ; refine' Finset.sum_congr rfl fun x hx => _ ; rw [ sum_Icc_one_id ] ; ring;
      have h_moebius_floor : ∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) * ((M / d : ℕ) : ℝ) = 1 := by
        convert congr_arg ( ( ↑ ) : ℤ → ℝ ) ( moebius_mul_floor_sum M hM ) using 1 ; norm_num [ Finset.sum_mul _ _ _ ];
        · exact Finset.sum_sdiff_eq_sum_sdiff_iff.mp rfl
        · norm_num;
      grind +splitIndPred;
    -- Using the bound from h_totient_bound, we can write
    have h_final_bound : ∀ M : ℕ, M ≥ 1 → |totientSum M - (3 / Real.pi ^ 2) * (M : ℝ) ^ 2| ≤ (2 * M * (1 + Real.log M) + M) / 2 + 1 / 2 := by
      exact fun M hM => le_trans ( h_totient_bound M hM ) ( by gcongr ; exact sum_Icc_one_div_le M );
    use 4;
    intro M hM; specialize h_final_bound M hM; refine le_trans h_final_bound ?_;
    nlinarith only [ show ( M : ℝ ) ≥ 1 by norm_cast, Real.log_nonneg ( show ( M : ℝ ) ≥ 1 by norm_cast ), Real.log_le_log ( by positivity ) ( show ( M : ℝ ) + 1 ≥ M by linarith ), Real.log_two_gt_d9, Real.log_le_log ( by positivity ) ( show ( M : ℝ ) + 1 ≥ 2 by norm_cast; linarith ) ];
  cases' h_C with C hC;
  refine' ⟨ Max.max C 0, le_max_right _ _, fun M => _ ⟩ ; by_cases hM : 1 ≤ M <;> simp_all +decide [ abs_le ];
  · exact ⟨ by nlinarith [ hC M hM, le_max_left C 0, le_max_right C 0, show ( 0 : ℝ ) ≤ M * Real.log ( M + 1 ) + 1 by exact add_nonneg ( mul_nonneg ( Nat.cast_nonneg _ ) ( Real.log_nonneg ( by linarith ) ) ) zero_le_one ], by nlinarith [ hC M hM, le_max_left C 0, le_max_right C 0, show ( 0 : ℝ ) ≤ M * Real.log ( M + 1 ) + 1 by exact add_nonneg ( mul_nonneg ( Nat.cast_nonneg _ ) ( Real.log_nonneg ( by linarith ) ) ) zero_le_one ] ⟩;
  · unfold totientSum; norm_num;

/-
Identity `2·Φ(M) = (∑_{d ≤ M} μ(d) ⌊M/d⌋²) + 1` for `M ≥ 1`.
-/
lemma two_totientSum_eq (M : ℕ) (hM : 1 ≤ M) :
    2 * totientSum M
      = (∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) * ((M / d : ℕ) : ℝ) ^ 2) + 1 := by
  convert congr_arg ( fun x : ℝ => x * 2 ) ( totientSum_rearrange M ) using 1;
  · ring;
  · rw [ Finset.sum_mul _ _ _ ];
    rw [ ← eq_sub_iff_add_eq' ];
    convert ( congr_arg ( fun x : ℤ => x : ℤ → ℝ ) ( moebius_mul_floor_sum M hM |> Eq.symm ) ) using 1;
    · norm_num;
    · rw [ ← Finset.sum_sub_distrib ] ; norm_cast ; norm_num [ sum_Icc_one_id ] ; ring;
      rw [ ← Finset.sum_sub_distrib ] ; refine' Finset.sum_congr rfl fun x hx => _ ; norm_cast ; aesop;

/-
Estimate `∑_{d ≤ M} μ(d) ⌊M/d⌋² = (6/π²) M² + O(M log M)`.
-/
lemma moebius_floorSq_error :
    ∃ C : ℝ, 0 ≤ C ∧ ∀ M : ℕ,
      |(∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) * ((M / d : ℕ) : ℝ) ^ 2)
          - (6 / Real.pi ^ 2) * (M : ℝ) ^ 2|
        ≤ C * ((M : ℝ) * Real.log (M + 1) + 1) := by
  obtain ⟨ C0, hC0nonneg, hC0 ⟩ := totientSum_error;
  refine' ⟨ 2 * C0 + 1, by positivity, fun M => _ ⟩ ; rcases eq_or_lt_of_le' M.zero_le with rfl | hM <;> norm_num at *;
  · positivity;
  · -- Let `S2 := ∑ d ∈ Icc 1 M, (moebius d:ℝ)*((M/d:ℕ):ℝ)^2`. By `two_totientSum_eq M hM`, `S2 = 2*totientSum M - 1`.
    set S2 := ∑ d ∈ Finset.Icc 1 M, (moebius d : ℝ) * ((M / d : ℕ) : ℝ) ^ 2
    have hS2 : S2 = 2 * totientSum M - 1 := by
      linarith [ two_totientSum_eq M hM ];
    refine' abs_le.mpr ⟨ _, _ ⟩ <;> ring_nf at *;
    · nlinarith [ abs_le.mp ( hC0 M ), show ( M : ℝ ) * Real.log ( 1 + M ) ≥ 0 by exact mul_nonneg ( Nat.cast_nonneg _ ) ( Real.log_nonneg ( by linarith ) ) ];
    · nlinarith [ abs_le.mp ( hC0 M ), show ( M : ℝ ) ≥ 1 by norm_cast, Real.log_nonneg ( show ( 1 + M : ℝ ) ≥ 1 by linarith ) ]

/-
Assembly at natural arguments: `∑_{d ≤ N} μ(d) Φ(⌊N/d⌋) = (18/π⁴) N² + O(N (log N)²)`.
-/
lemma Anat_error :
    ∃ C : ℝ, 0 ≤ C ∧ ∀ N : ℕ,
      |(∑ d ∈ Finset.Icc 1 N, (moebius d : ℝ) * totientSum (N / d))
          - (18 / Real.pi ^ 4) * (N : ℝ) ^ 2|
        ≤ C * ((N : ℝ) * (Real.log (N + 1)) ^ 2 + 1) := by
  -- By combining the results from `totientSum_error` and `moebius_floorSq_error`, we can bound the error term.
  obtain ⟨C0, hC0nn, hC0⟩ := totientSum_error
  obtain ⟨C1, hC1nn, hC1⟩ := moebius_floorSq_error;
  -- Using the bounds from `hC0` and `hC1`, we can bound the error term.
  have h_error_bound : ∀ N : ℕ, |∑ d ∈ Finset.Icc 1 N, (moebius d : ℝ) * (totientSum (N / d)) - (3 / Real.pi ^ 2) * (∑ d ∈ Finset.Icc 1 N, (moebius d : ℝ) * ((N / d : ℕ) : ℝ) ^ 2)| ≤ C0 * (N * Real.log (N + 1) * (1 + Real.log N) + N) := by
    intros N
    have h_error_bound_step : ∀ d ∈ Finset.Icc 1 N, |(moebius d : ℝ) * (totientSum (N / d) - (3 / Real.pi ^ 2) * ((N / d : ℕ) : ℝ) ^ 2)| ≤ C0 * ((N / d : ℕ) * Real.log (N + 1) + 1) := by
      intros d hd
      have h_abs : |(moebius d : ℝ)| ≤ 1 := by
        norm_num [ moebius ];
        split_ifs <;> norm_num;
      rw [ abs_mul ];
      refine' le_trans ( mul_le_of_le_one_left ( abs_nonneg _ ) h_abs ) ( le_trans ( hC0 _ ) _ );
      exact mul_le_mul_of_nonneg_left ( add_le_add ( mul_le_mul_of_nonneg_left ( Real.log_le_log ( by positivity ) ( by norm_cast; nlinarith [ Nat.div_mul_le_self N d, Finset.mem_Icc.mp hd ] ) ) ( by positivity ) ) le_rfl ) hC0nn;
    have h_error_bound_sum : ∑ d ∈ Finset.Icc 1 N, C0 * ((N / d : ℕ) * Real.log (N + 1) + 1) ≤ C0 * (N * Real.log (N + 1) * (1 + Real.log N) + N) := by
      have h_error_bound_sum : ∑ d ∈ Finset.Icc 1 N, (N / d : ℕ) ≤ N * (1 + Real.log N) := by
        have h_error_bound_sum : ∑ d ∈ Finset.Icc 1 N, (N / d : ℕ) ≤ N * ∑ d ∈ Finset.Icc 1 N, (1 / (d : ℝ)) := by
          norm_num [ Finset.mul_sum _ _ _ ];
          exact Finset.sum_le_sum fun x hx => by rw [ ← div_eq_mul_inv ] ; rw [ le_div_iff₀ ( Nat.cast_pos.mpr <| Finset.mem_Icc.mp hx |>.1 ) ] ; norm_cast; linarith [ Nat.div_mul_le_self N x ] ;
        exact h_error_bound_sum.trans ( mul_le_mul_of_nonneg_left ( sum_Icc_one_div_le N ) ( Nat.cast_nonneg _ ) );
      simp_all +decide [ mul_comm, mul_left_comm ];
      norm_num [ Finset.sum_add_distrib, ← Finset.mul_sum _ _ _, ← Finset.sum_mul ];
      exact mul_le_mul_of_nonneg_left ( by nlinarith [ Real.log_nonneg ( show ( N:ℝ ) + 1 ≥ 1 by linarith ) ] ) hC0nn;
    convert le_trans ( Finset.abs_sum_le_sum_abs _ _ ) ( Finset.sum_le_sum h_error_bound_step ) |> le_trans <| h_error_bound_sum using 1 ; norm_num [ mul_sub, Finset.mul_sum _ _ _, Finset.sum_mul ] ; ring;
  -- Combining the bounds from `h_error_bound` and `hC1`, we get the desired result.
  have h_combined : ∀ N : ℕ, |∑ d ∈ Finset.Icc 1 N, (moebius d : ℝ) * (totientSum (N / d)) - (18 / Real.pi ^ 4) * (N : ℝ) ^ 2| ≤ C0 * (N * Real.log (N + 1) * (1 + Real.log N) + N) + (3 / Real.pi ^ 2) * C1 * (N * Real.log (N + 1) + 1) := by
    intro N; specialize h_error_bound N; specialize hC1 N; rw [ abs_le ] at *; constructor <;> ring_nf at * <;> nlinarith [ inv_pos.mpr ( pow_pos Real.pi_pos 2 ), inv_pos.mpr ( pow_pos Real.pi_pos 4 ), mul_inv_cancel₀ ( ne_of_gt ( pow_pos Real.pi_pos 2 ) ), mul_inv_cancel₀ ( ne_of_gt ( pow_pos Real.pi_pos 4 ) ) ] ;
  -- We can choose $C$ large enough to cover both terms in the combined bound.
  obtain ⟨C, hC⟩ : ∃ C : ℝ, 0 ≤ C ∧ ∀ N : ℕ, N ≥ 3 → C0 * (N * Real.log (N + 1) * (1 + Real.log N) + N) + (3 / Real.pi ^ 2) * C1 * (N * Real.log (N + 1) + 1) ≤ C * (N * (Real.log (N + 1)) ^ 2 + 1) := by
    refine' ⟨ 4 * C0 + 4 * ( 3 / Real.pi ^ 2 ) * C1 + 1, by positivity, fun N hN => _ ⟩ ; ring_nf;
    -- We'll use that $Real.log (1 + N) \geq 1$ for $N \geq 3$.
    have h_log_bound : Real.log (1 + N) ≥ 1 := by
      exact Real.le_log_iff_exp_le ( by positivity ) |>.2 ( by exact Real.exp_one_lt_d9.le.trans ( by norm_num; linarith [ show ( N : ℝ ) ≥ 3 by norm_cast ] ) );
    have h_log_bound : Real.log N ≤ Real.log (1 + N) := by
      exact Real.log_le_log ( by positivity ) ( by linarith );
    nlinarith [ show ( N : ℝ ) ≥ 3 by norm_cast, show ( 0 : ℝ ) ≤ C0 * N by positivity, show ( 0 : ℝ ) ≤ C0 * N * Real.log ( 1 + N ) by positivity, show ( 0 : ℝ ) ≤ C0 * N * Real.log ( 1 + N ) * Real.log N by positivity, show ( 0 : ℝ ) ≤ N * Real.log ( 1 + N ) * Real.pi⁻¹ ^ 2 * C1 by positivity, show ( 0 : ℝ ) ≤ Real.pi⁻¹ ^ 2 * C1 by positivity, mul_le_mul_of_nonneg_left h_log_bound <| show ( 0 : ℝ ) ≤ C0 * N by positivity, mul_le_mul_of_nonneg_left h_log_bound <| show ( 0 : ℝ ) ≤ N * Real.log ( 1 + N ) * Real.pi⁻¹ ^ 2 * C1 by positivity ];
  refine' ⟨ Max.max C ( ∑ N ∈ Finset.range 3, |∑ d ∈ Finset.Icc 1 N, ( moebius d : ℝ ) * totientSum ( N / d ) - 18 / Real.pi ^ 4 * ( N : ℝ ) ^ 2| ), _, _ ⟩ <;> norm_num;
  · exact Or.inl hC.1;
  · intro N; by_cases hN : N < 3;
    · refine' le_trans _ ( le_mul_of_one_le_right _ _ );
      · exact le_max_of_le_right ( Finset.single_le_sum ( fun N _ => abs_nonneg ( ∑ d ∈ Finset.Icc 1 N, ( moebius d : ℝ ) * totientSum ( N / d ) - 18 / Real.pi ^ 4 * ( N : ℝ ) ^ 2 ) ) ( Finset.mem_range.mpr hN ) );
      · exact le_max_of_le_left hC.1;
      · exact le_add_of_nonneg_left ( by positivity );
    · exact le_trans ( h_combined N ) ( le_trans ( hC.2 N ( le_of_not_gt hN ) ) ( mul_le_mul_of_nonneg_right ( le_max_left _ _ ) ( by positivity ) ) )

/-
**Main theorem.**  The number `A(X)` of primitive Dirichlet characters of modulus at most `X`
satisfies `A(X) = (18/π⁴) X² + O(X (log X)²)`.

Remarks on the statement (see the file header): the leading constant is `18/π⁴`, correcting the
`3/π²` in the original problem statement.  The error term is `O(X (log X)²)`, the bound delivered by
the elementary hyperbola method used here; the sharper `O(X log X)` requested in the problem (and
even `O(X)`, which numerics suggest) also holds, but requires additional Möbius-cancellation
estimates not carried out here.
-/
theorem A_asymptotic :
    (fun x : ℝ => A x - (18 / Real.pi ^ 4) * x ^ 2)
      =O[atTop] fun x : ℝ => x * (Real.log x) ^ 2 := by
  obtain ⟨ C, hCnn, hC ⟩ := Anat_error;
  refine' Asymptotics.IsBigO.of_bound ( 4*C + 18 / Real.pi ^ 4 * 2 + C + 1 ) ( Filter.eventually_atTop.mpr ⟨ 8, fun x hx => _ ⟩ );
  -- Substitute the bounds from `hC` and simplify.
  have h_bound : |A x - (18 / Real.pi ^ 4) * x ^ 2| ≤ C * (x * (Real.log (x + 1)) ^ 2 + 1) + (18 / Real.pi ^ 4) * 2 * x := by
    have h_bound : |A x - (18 / Real.pi ^ 4) * (⌊x⌋₊ : ℝ) ^ 2| ≤ C * (x * (Real.log (x + 1)) ^ 2 + 1) := by
      refine' le_trans _ ( le_trans ( hC ⌊x⌋₊ ) _ );
      · rw [ A_eq_moebius_totientSum ];
      · gcongr;
        · exact Nat.floor_le ( by positivity );
        · exact Real.log_nonneg ( by linarith );
        · exact Nat.floor_le ( by positivity );
    rw [ abs_le ] at *;
    constructor <;> nlinarith [ Nat.floor_le ( show 0 ≤ x by linarith ), Nat.lt_floor_add_one x, show ( 0 : ℝ ) ≤ 18 / Real.pi ^ 4 by positivity, show ( 0 : ℝ ) ≤ 18 / Real.pi ^ 4 * x by positivity, show ( 0 : ℝ ) ≤ 18 / Real.pi ^ 4 * ⌊x⌋₊ by positivity ];
  -- We'll use that $Real.log (x + 1) \leq 2 * Real.log x$ for $x \geq 8$.
  have h_log_bound : Real.log (x + 1) ≤ 2 * Real.log x := by
    rw [ ← Real.log_rpow, Real.log_le_log_iff ] <;> norm_num <;> nlinarith;
  -- We'll use that $Real.log x \geq 1$ for $x \geq 8$.
  have h_log_ge_one : 1 ≤ Real.log x := by
    exact Real.le_log_iff_exp_le ( by positivity ) |>.2 ( by exact Real.exp_one_lt_d9.le.trans ( by norm_num; linarith ) );
  rw [ Real.norm_of_nonneg ( by positivity : 0 ≤ x * Real.log x ^ 2 ) ];
  refine le_trans h_bound ?_;
  refine' le_trans ( add_le_add ( mul_le_mul_of_nonneg_left ( add_le_add ( mul_le_mul_of_nonneg_left ( pow_le_pow_left₀ ( Real.log_nonneg ( by linarith ) ) h_log_bound 2 ) ( by positivity ) ) le_rfl ) hCnn ) le_rfl ) _;
  nlinarith [ show 0 ≤ C * x by positivity, show 0 ≤ 18 / Real.pi ^ 4 * x by positivity, show 0 ≤ C * x * Real.log x ^ 2 by positivity, show 0 ≤ 18 / Real.pi ^ 4 * x * Real.log x ^ 2 by positivity, Real.pi_gt_three, mul_le_mul_of_nonneg_left h_log_ge_one <| show 0 ≤ x by positivity, mul_le_mul_of_nonneg_left h_log_ge_one <| show 0 ≤ C * x by positivity, mul_le_mul_of_nonneg_left h_log_ge_one <| show 0 ≤ 18 / Real.pi ^ 4 * x by positivity ]

end

